/* ------------------------------------------------------------------ */
/* First-run wizard — scoped to the onboarding module                 */
/* ------------------------------------------------------------------ */

.wizard-backdrop {
  position: fixed;
  inset: 0;
  z-index: 950;
  display: grid;
  place-items: center;
  padding: 24px;
  background: radial-gradient(
    120% 90% at 50% 0%,
    rgba(12, 16, 28, 0.72),
    rgba(3, 5, 10, 0.88)
  );
  backdrop-filter: blur(14px) saturate(120%);
  animation: wizard-fade 200ms ease-out both;
}

.wizard-panel {
  position: relative;
  width: min(720px, 100%);
  min-height: min(540px, 82vh);
  max-height: min(88vh, 760px);
  display: flex;
  flex-direction: column;
  border-radius: 20px;
  border: 1px solid rgba(255, 255, 255, 0.09);
  background: linear-gradient(180deg, #161b28 0%, #0b0e15 100%);
  box-shadow:
    0 40px 120px -20px rgba(0, 0, 0, 0.85),
    0 0 0 1px rgba(0, 0, 0, 0.35),
    inset 0 1px 0 rgba(255, 255, 255, 0.06);
  overflow: hidden;
  animation: wizard-enter 320ms cubic-bezier(0.16, 1, 0.3, 1) both;
}

.wizard-panel::before {
  content: "";
  position: absolute;
  pointer-events: none;
  top: -180px;
  right: 0;
  left: 0;
  height: 340px;
  background: radial-gradient(60% 100% at 50% 0%, rgba(99, 102, 241, 0.2), transparent 75%);
}

.wizard-panel:focus,
.wizard-title:focus {
  outline: none;
}

.wizard-head {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 22px 30px 14px;
}

.wizard-wordmark {
  font-size: 0.68rem;
  font-weight: 600;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: rgba(226, 232, 240, 0.55);
}

.wizard-count {
  font-size: 0.72rem;
  color: var(--studio-muted);
  font-variant-numeric: tabular-nums;
}

.wizard-progress {
  position: relative;
  z-index: 1;
  display: flex;
  gap: 5px;
  margin: 0;
  padding: 0 30px;
  list-style: none;
}

.wizard-progress__item {
  flex: 1;
  height: 2px;
  border-radius: 2px;
  background: rgba(255, 255, 255, 0.08);
}

.wizard-progress__item.is-done {
  background: rgba(129, 140, 248, 0.55);
}

.wizard-progress__item.is-current {
  background: linear-gradient(90deg, var(--studio-indigo-strong), rgba(129, 140, 248, 0.25));
}

.wizard-body {
  position: relative;
  z-index: 1;
  padding: 20px 30px 10px;
  overflow-y: auto;
  overscroll-behavior: contain;
  animation: wizard-rise 280ms cubic-bezier(0.16, 1, 0.3, 1) both;
}

.wizard-title {
  margin: 0 0 12px;
  max-width: 34ch;
  font-size: clamp(1.6rem, 2.6vw, 2.05rem);
  font-weight: 650;
  line-height: 1.1;
  letter-spacing: -0.035em;
  color: #f8fafc;
}

.wizard-lead {
  margin: 0 0 26px;
  max-width: 56ch;
  font-size: 0.97rem;
  line-height: 1.62;
  color: #c3cddc;
}

.wizard-hint {
  margin: 0;
  font-size: 0.78rem;
  color: rgba(148, 163, 184, 0.8);
}

.wizard-sr {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ------------------------------------------------------------------ */
/* Step 1 — the three moves                                           */
/* ------------------------------------------------------------------ */

.wizard-moves {
  display: grid;
  gap: 10px;
  margin: 0 0 8px;
  padding: 0;
  list-style: none;
}

.wizard-move {
  display: grid;
  grid-template-columns: 44px 1fr;
  gap: 14px;
  padding: 13px 16px;
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.05);
  background: rgba(255, 255, 255, 0.018);
}

.wizard-move__index {
  padding-top: 3px;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 0.72rem;
  letter-spacing: 0.05em;
  color: rgba(129, 140, 248, 0.75);
}

.wizard-move__title {
  display: block;
  font-size: 0.94rem;
  font-weight: 600;
  color: #eef2f8;
}

.wizard-move__detail {
  display: block;
  margin-top: 2px;
  font-size: 0.84rem;
  line-height: 1.5;
  color: var(--studio-muted);
}

/* ------------------------------------------------------------------ */
/* Step 2 — goal cards                                                */
/* ------------------------------------------------------------------ */

.wizard-goals {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin-bottom: 12px;
}

.wizard-goal {
  display: grid;
  grid-template-columns: 34px 1fr;
  gap: 12px;
  align-items: start;
  padding: 14px 15px;
  border-radius: 14px;
  border: 1px solid var(--studio-border);
  background: rgba(255, 255, 255, 0.02);
  color: inherit;
  text-align: left;
  cursor: pointer;
  transition:
    border-color 0.16s ease,
    background 0.16s ease,
    transform 0.16s ease;
}

.wizard-goal:hover {
  border-color: rgba(129, 140, 248, 0.4);
  background: rgba(129, 140, 248, 0.06);
}

.wizard-goal:active {
  transform: scale(0.995);
}

.wizard-goal[aria-pressed="true"] {
  border-color: rgba(129, 140, 248, 0.65);
  background: rgba(99, 102, 241, 0.13);
  box-shadow: inset 0 0 0 1px rgba(129, 140, 248, 0.18);
}

.wizard-goal__icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: none;
  width: 34px;
  height: 34px;
  border-radius: 10px;
  border: 1px solid rgba(99, 102, 241, 0.22);
  background: rgba(99, 102, 241, 0.12);
  color: var(--studio-indigo);
}

.wizard-goal[aria-pressed="true"] .wizard-goal__icon {
  background: rgba(99, 102, 241, 0.24);
  color: #c7d2fe;
}

.wizard-goal__title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  font-size: 0.92rem;
  font-weight: 600;
  color: #f1f5f9;
}

.wizard-goal__check {
  font-size: 0.82rem;
  color: var(--studio-green);
}

.wizard-goal__blurb {
  display: block;
  margin-top: 4px;
  font-size: 0.81rem;
  line-height: 1.5;
  color: var(--studio-muted);
}

/* ------------------------------------------------------------------ */
/* Step 3 — instruments                                               */
/* ------------------------------------------------------------------ */

.wizard-checks {
  display: grid;
  gap: 2px;
  margin-bottom: 22px;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
}

.wizard-check {
  display: grid;
  grid-template-columns: 8px 1fr auto;
  gap: 12px;
  align-items: center;
  padding: 13px 2px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}

.wizard-check__dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--studio-muted);
}

.wizard-check--ok .wizard-check__dot {
  background: var(--studio-green);
  box-shadow: 0 0 8px rgba(52, 211, 153, 0.45);
}

.wizard-check--warn .wizard-check__dot {
  background: var(--studio-amber);
  box-shadow: 0 0 8px rgba(251, 191, 36, 0.35);
}

.wizard-check--pending .wizard-check__dot {
  background: var(--studio-indigo);
  animation: wizard-pulse 1.2s infinite ease-in-out;
}

.wizard-check__label {
  display: block;
  font-size: 0.9rem;
  font-weight: 500;
  color: #e8eef7;
}

.wizard-check__detail {
  display: block;
  margin-top: 1px;
  font-size: 0.78rem;
  color: var(--studio-muted);
}

.wizard-check__state {
  font-size: 0.78rem;
  color: var(--studio-muted);
}

.wizard-check--ok .wizard-check__state {
  color: var(--studio-green);
}

.wizard-check--warn .wizard-check__state {
  color: var(--studio-amber);
}

.wizard-config {
  margin-bottom: 10px;
  padding: 16px;
  border-radius: 12px;
  border: 1px solid rgba(251, 191, 36, 0.18);
  background: rgba(251, 191, 36, 0.045);
}

.wizard-config__hint {
  margin: 0 0 14px;
  font-size: 0.84rem;
  line-height: 1.55;
  color: #d6dde8;
}

.wizard-config__message {
  margin: 0 0 12px;
  font-size: 0.8rem;
  color: var(--studio-amber);
}

.wizard-config__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0 12px;
}

.wizard-config__key {
  grid-column: 1 / -1;
}

.wizard-config__actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.wizard-config__status {
  font-size: 0.78rem;
  color: var(--studio-muted);
}

/* ------------------------------------------------------------------ */
/* Step 4 — first move                                                */
/* ------------------------------------------------------------------ */

.wizard-launch {
  display: grid;
  gap: 16px;
}

.wizard-launch__choice {
  display: flex;
  align-items: center;
  gap: 12px;
}

.wizard-launch__title {
  display: block;
  font-size: 0.95rem;
  font-weight: 600;
  color: #f1f5f9;
}

.wizard-launch__result {
  display: block;
  margin-top: 2px;
  font-size: 0.83rem;
  color: var(--studio-muted);
}

.wizard-quote__label {
  margin: 0;
  font-size: 0.68rem;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: rgba(148, 163, 184, 0.75);
}

.wizard-quote {
  margin: -6px 0 0;
  padding: 14px 18px;
