       addObservation,
       updateObservation,
       clearMemory,
       addStep,
       addOutcome,
       pendingSimOutcome,
       requestSimulate,
       clearPendingSimOutcome,
       activeTab,
       setActiveTab,
       toasts,
       pushToast,
       dismissToast,
     }),
     [
       settings,
       saveSettings,
       canvas,
       canvasLoading,
       canvasCached,
       refreshCanvas,
       llmHealth,
       mcpReachable,
       sidecarReachable,
       checkConnections,
       messages,
       conversationId,
       streaming,
       thinkingPhase,
       toolActivity,
       sendMessage,
       clearChat,
       memory,
       memoryLoading,
       refreshMemory,
       addObservation,
       updateObservation,
       clearMemory,
       addStep,
       addOutcome,
       pendingSimOutcome,
       requestSimulate,
       clearPendingSimOutcome,
       activeTab,
       engagementLevel,
       saveEngagementLevel,
       toasts,
       pushToast,
       dismissToast,
     ],
   );

