import { fireEvent, render, screen } from "@testing-library/react";
import { beforeEach, describe, expect, it, vi } from "vitest";

const studio = vi.hoisted(() => ({
  llmHealth: { healthy: true, message: "ok" },
  mcpReachable: true,
  engagementLevel: 0,
  setEngagementLevel: vi.fn(),
}));

vi.mock("../state/StudioContext", () => ({
  useStudio: () => studio,
}));

import { StudioHeader } from "./StudioHeader";

describe("StudioHeader settings toggle", () => {
  beforeEach(() => {
    studio.engagementLevel = 0;
    studio.setEngagementLevel.mockClear();
  });

  it("opens settings from the first-run shell", () => {
    render(<StudioHeader />);

    fireEvent.click(screen.getByRole("button", { name: "Open studio settings" }));

    expect(studio.setEngagementLevel).toHaveBeenCalledWith(2);
  });

  it("closes settings when they are already open", () => {
    studio.engagementLevel = 2;
    render(<StudioHeader />);

    const button = screen.getByRole("button", { name: "Close studio settings" });
    expect(button).toHaveAttribute("aria-expanded", "true");
    fireEvent.click(button);

    expect(studio.setEngagementLevel).toHaveBeenCalledWith(1);
  });
